puzzle-rename-var.start:
export function summarize(data: number[], meta: Meta): Summary {
  const total = data.reduce((sum, n) => sum + n, 0);
  const mean = data.length > 0 ? total / data.length : 0;
  return {
    metadata: meta,
    stats: { total, mean },
  };
}

puzzle-rename-var.doc:
export function summarize(payload: number[], meta: Meta): Summary {
  const total = payload.reduce((sum, n) => sum + n, 0);
  const mean = payload.length > 0 ? total / payload.length : 0;
  return {
    metadata: meta,
    stats: { total, mean },
  };
}

